activepieces.compose:
# documentation: https://www.activepieces.com/docs/getting-started/introduction
# slogan: Open source no-code business automation.
# category: automation
# tags: workflow, automation, no code, open source
# logo: svgs/activepieces.png
# port: 80

services:
  activepieces:
    image: ghcr.io/activepieces/activepieces:0.75.0
    environment:
      - SERVICE_URL_ACTIVEPIECES
      - AP_API_KEY=$SERVICE_PASSWORD_64_APIKEY
      - AP_ENCRYPTION_KEY=$SERVICE_PASSWORD_ENCRYPTIONKEY
      - AP_ENGINE_EXECUTABLE_PATH=${AP_ENGINE_EXECUTABLE_PATH:-dist/packages/engine/main.js}
      - AP_ENVIRONMENT=${AP_ENVIRONMENT:-prod}
      - AP_EXECUTION_MODE=${AP_EXECUTION_MODE:-UNSANDBOXED}
      - AP_FRONTEND_URL=${SERVICE_URL_ACTIVEPIECES}
      - AP_JWT_SECRET=$SERVICE_PASSWORD_64_JWT
      - AP_POSTGRES_DATABASE=${POSTGRES_DB:-activepieces}
      - AP_POSTGRES_HOST=${POSTGRES_HOST:-postgres}
      - AP_POSTGRES_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - AP_POSTGRES_PORT=${POSTGRES_PORT:-5432}
      - AP_POSTGRES_USERNAME=$SERVICE_USER_POSTGRES
      - AP_REDIS_HOST=${REDIS_HOST:-redis}
      - AP_REDIS_PORT=${REDIS_PORT:-6379}
      - AP_SANDBOX_RUN_TIME_SECONDS=${AP_SANDBOX_RUN_TIME_SECONDS:-600}
      - AP_TELEMETRY_ENABLED=${AP_TELEMETRY_ENABLED:-false}
      - AP_TEMPLATES_SOURCE_URL=${AP_TEMPLATES_SOURCE_URL:-https://cloud.activepieces.com/api/v1/flow-templates}
      - AP_TRIGGER_DEFAULT_POLL_INTERVAL=${AP_TRIGGER_DEFAULT_POLL_INTERVAL:-5}
      - AP_SIGN_UP_ENABLED=${AP_SIGN_UP_ENABLED:-true}
      - AP_WEBHOOK_TIMEOUT_SECONDS=${AP_WEBHOOK_TIMEOUT_SECONDS:-30}
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_started
    healthcheck:
      test: ["CMD", "curl", "-f", "http://127.0.0.1:80"]
      interval: 5s
      timeout: 20s
      retries: 10
  postgres:
    image: postgres:18-alpine
    environment:
      - POSTGRES_DB=${POSTGRES_DB:-activepieces}
      - POSTGRES_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - POSTGRES_USER=${SERVICE_USER_POSTGRES}
      - POSTGRES_PORT=${POSTGRES_PORT:-5432}
    volumes:
      - 'pg-data:/var/lib/postgresql'
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U $${POSTGRES_USER} -d $${POSTGRES_DB}"]
      interval: 5s
      timeout: 20s
      retries: 10
  redis:
    image: redis:7-alpine
    volumes:
      - "redis_data:/data"
    healthcheck:
      test: ["CMD", "redis-cli", "ping"]
      interval: 5s
      timeout: 20s
      retries: 10

alexandrie.compose:
# documentation: https://github.com/Smaug6739/Alexandrie/tree/main/docs
# slogan: A powerful Markdown workspace designed for speed, clarity, and creativity.
# category: productivity
# tags: note-taking, markdown, knowledge-management, personal-wiki, productivity
# logo: svgs/alexandrie.svg
# port: 8200

services:
  frontend:
    image: ghcr.io/smaug6739/alexandrie-frontend:v8.7.2
    environment:
      - SERVICE_URL_FRONTEND_8200
      - PORT=8200
      - NUXT_PUBLIC_CONFIG_DISABLE_SIGNUP_PAGE=${CONFIG_DISABLE_SIGNUP:-false}
      - NUXT_PUBLIC_CONFIG_DISABLE_LANDING_PAGE=${CONFIG_DISABLE_LANDING:-false}
      - NUXT_PUBLIC_BASE_API=${SERVICE_URL_BACKEND}
      - NUXT_PUBLIC_BASE_CDN=${SERVICE_URL_RUSTFS}
      - NUXT_PUBLIC_CDN_ENDPOINT=${CDN_ENDPOINT:-/alexandrie/}
      - NUXT_PUBLIC_BASE_URL=${SERVICE_URL_FRONTEND}
    depends_on:
      - backend

  backend:
    image: ghcr.io/smaug6739/alexandrie-backend:v8.7.2
    environment:
      - SERVICE_URL_BACKEND_8201
      - BACKEND_PORT=8201
      - GIN_MODE=release
      - JWT_SECRET=${SERVICE_PASSWORD_JWT}
      - COOKIE_DOMAIN=${SERVICE_URL_FRONTEND}
      - FRONTEND_URL=${SERVICE_URL_FRONTEND}
      - ALLOW_UNSECURE=${ALLOW_UNSECURE:-false}
      - DATABASE_HOST=mysql
      - DATABASE_PORT=3306
      - DATABASE_NAME=${MYSQL_DATABASE:-alexandrie-db}
      - DATABASE_USER=${SERVICE_USER_MYSQL}
      - DATABASE_PASSWORD=${SERVICE_PASSWORD_MYSQL}
      - MINIO_ENDPOINT=rustfs:9000
      - MINIO_PUBLIC_URL=${SERVICE_URL_RUSTFS}
      - MINIO_SECURE=${MINIO_SECURE:-false}
      - MINIO_ACCESSKEY=${SERVICE_USER_RUSTFS}
      - MINIO_SECRETKEY=${SERVICE_PASSWORD_RUSTFS}
      - MINIO_BUCKET=${MINIO_BUCKET:-alexandrie}
      - SMTP_HOST=${SMTP_HOST:-}
      - SMTP_MAIL=${SMTP_MAIL:-}
      - SMTP_PASSWORD=${SMTP_PASSWORD:-}
    depends_on:
      mysql:
        condition: service_healthy
      rustfs:
        condition: service_healthy

  mysql:
    image: mysql:8.0
    environment:
      - MYSQL_ROOT_PASSWORD=${SERVICE_PASSWORD_MYSQLROOT}
      - MYSQL_USER=${SERVICE_USER_MYSQL}
      - MYSQL_PASSWORD=${SERVICE_PASSWORD_MYSQL}
      - MYSQL_DATABASE=${MYSQL_DATABASE:-alexandrie-db}
    volumes:
      - mysql-data:/var/lib/mysql
    healthcheck:
      test:
        - CMD
        - mysqladmin
        - ping
        - "-h"
        - localhost
        - "-u"
        - root
        - "-p${SERVICE_PASSWORD_MYSQLROOT}"
      timeout: 5s
      interval: 10s
      retries: 5

  rustfs:
    image: rustfs/rustfs:1.0.0-alpha.90
    environment:
      - SERVICE_URL_RUSTFS_9000
      - RUSTFS_ACCESS_KEY=${SERVICE_USER_RUSTFS}
      - RUSTFS_SECRET_KEY=${SERVICE_PASSWORD_RUSTFS}
      - RUSTFS_CONSOLE_ENABLE=${RUSTFS_CONSOLE_ENABLE:-false}
      - RUSTFS_LOG_LEVEL=${RUSTFS_LOG_LEVEL:-info}
    volumes:
      - rustfs-data:/data
      - rustfs-logs:/logs
    healthcheck:
      test:
        - CMD-SHELL
        - "nc -z localhost 9000 || exit 1"
      interval: 10s
      timeout: 5s
      retries: 5

anythingllm.compose:
# documentation: https://docs.anythingllm.com/installation-docker/overview
# slogan: AnythingLLM is the easiest to use, all-in-one AI application that can do RAG, AI Agents, and much more with no code or infrastructure headaches.
# category: ai
# tags: lowcode, nocode, llm, openai, anthropic, machine-learning, rag, agents, chatbot, api, team, bot
# logo: svgs/anythingllm.svg
# port: 3001

services:
  anything-llm:
    image: mintplexlabs/anythingllm
    environment:
      - SERVICE_URL_ANYTHINGLLM_3001
      - STORAGE_DIR=/app/server/storage
      - DISABLE_TELEMETRY=${DISABLE_TELEMETRY:-true}
      - PASSWORDLOWERCASE=${PASSWORDLOWERCASE:-1}
      - PASSWORDMAXCHAR=${PASSWORDMAXCHAR:-250}
      - PASSWORDMINCHAR=${PASSWORDMINCHAR:-6}
      - PASSWORDNUMERIC=${PASSWORDNUMERIC:-1}
      - PASSWORDREQUIREMENTS=${PASSWORDREQUIREMENTS:-1}
      - PASSWORDSYMBOL=${PASSWORDSYMBOL:-1}
      - PASSWORDUPPERCASE=${PASSWORDUPPERCASE:-1}
      - SIG_KEY=${SERVICE_PASSWORD_SIGKEY}
      - SIG_SALT=${SERVICE_PASSWORD_SIGSALT}
      - JWT_SECRET=${SERVICE_PASSWORD_JWTSECRET}
      - AUTH_TOKEN=${SERVICE_PASSWORD_AUTHTOKEN}
      - SERVER_PORT=${SERVER_PORT:-3001}
      - VECTOR_DB=lancedb
    cap_add:
      - SYS_ADMIN
    volumes:
      - "anythingllm-storage:/app/server/storage"
      - "anythingllm-hot:/app/collector/hotdir"
      - "anythingllm-outputs:/app/collector/outputs"
    user: "${UID:-1000}:${GID:-1000}"

appflowy.compose:
# documentation: https://docs.appflowy.io/docs/documentation/appflowy-cloud
# slogan: AppFlowy is the AI collaborative workspace where you achieve more without losing control of your data.
# tags: appflowy,notion,open-source,productivity,notes,ai,self-hosted
# logo: svgs/appflowy.svg
# category: productivity
# port: 80

services:
  nginx:
    image: nginx:1.29.2
    environment:
      - SERVICE_URL_ADMIN
    volumes:
      - type: bind
        source: ./nginx/nginx.conf
        target: /etc/nginx/nginx.conf
        read_only: true
        content: |
          # Please do not directly edit this file.

          error_log  /var/log/nginx/error.log notice;
          pid        /var/run/nginx.pid;


          events {
              worker_connections  1024;
          }


          http {
              resolver 127.0.0.11 valid=10s;
              map $http_upgrade $connection_upgrade {
                  default upgrade;
                  '' close;
              }

              server {
                  listen 80;
                  client_max_body_size 10M;
                  underscores_in_headers on;

                  # Backend services
                  set $appflowy_cloud_backend "http://appflowy_cloud:8000";
                  set $gotrue_backend "http://gotrue:9999";
                  set $admin_frontend_backend "http://admin_frontend:3000";
                  # GoTrue Authentication Service
                  location /gotrue/ {
                      proxy_pass $gotrue_backend;

                      rewrite ^/gotrue(/.*)$ $1 break;

                      # Allow headers like redirect_to to be handed over to the gotrue
                      # for correct redirecting
                      proxy_set_header Host $http_host;
                      proxy_pass_request_headers on;
                  }

                  # WebSocket endpoint - handle both /ws and /ws/v2
                  location /ws {
                      proxy_pass $appflowy_cloud_backend;

                      proxy_http_version 1.1;
                      proxy_set_header Upgrade $http_upgrade;
                      proxy_set_header Connection "Upgrade";
                      proxy_set_header Host $host;
                      proxy_set_header X-Real-IP $remote_addr;
                      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
                      proxy_set_header X-Forwarded-Proto $scheme;
                      proxy_read_timeout 86400s;
                  }

                  # API endpoints
                  location /api {
                      proxy_pass $appflowy_cloud_backend;
                      proxy_set_header X-Request-Id $request_id;
                      proxy_set_header Host $http_host;

                      # Special handling for publish endpoint
                      location ~* ^/api/workspace/([a-zA-Z0-9_-]+)/publish$ {
                          proxy_pass $appflowy_cloud_backend;
                          proxy_request_buffering off;
                          client_max_body_size 256M;
                      }

                      # Chat endpoint (streaming)
                      location /api/chat {
                          proxy_pass $appflowy_cloud_backend;

                          proxy_http_version 1.1;
                          proxy_set_header Connection "";
                          chunked_transfer_encoding on;
                          proxy_buffering off;
                          proxy_cache off;

                          proxy_read_timeout 600s;
                          proxy_connect_timeout 600s;
                          proxy_send_timeout 600s;
                      }

                      # Import endpoint
                      location /api/import {
                          proxy_pass $appflowy_cloud_backend;

                          proxy_set_header X-Request-Id $request_id;
                          proxy_set_header Host $http_host;

                          proxy_read_timeout 600s;
                          proxy_connect_timeout 600s;
                          proxy_send_timeout 600s;

                          proxy_request_buffering off;
                          proxy_buffering off;
                          proxy_cache off;
                          client_max_body_size 2G;
                      }
                  }

                  # Admin Frontend
                  # Optional Module, comment this section if you did not deploy admin_frontend in docker-compose.yml
                  location /console {
                      proxy_pass $admin_frontend_backend;

                      proxy_set_header X-Scheme $scheme;
                      proxy_set_header Host $host;
                      proxy_set_header X-Real-IP $remote_addr;
                      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
                      proxy_set_header X-Forwarded-Proto $scheme;

                      proxy_http_version 1.1;
                      proxy_set_header Connection "";

                      proxy_buffering off;
                      proxy_cache off;

                      proxy_read_timeout 60s;
                      proxy_connect_timeout 60s;
                      proxy_send_timeout 60s;
                  }

                  # Redirect root path to /console
                  location = / {
                      return 301 /console;
                  }

                  # Health check endpoint
                  location /health {
                      access_log off;
                      return 200 "healthy\n";
                      add_header Content-Type text/plain;
                  }
              }
          }
    depends_on:
      - appflowy_cloud
      - gotrue
      - admin_frontend
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost/health"]
      interval: 30s
      timeout: 10s
      retries: 3
      start_period: 40s

  appflowy_web:
    environment:
      - SERVICE_URL_APPFLOWYWEB
      - APPFLOWY_BASE_URL=${SERVICE_URL_ADMIN}
      - APPFLOWY_GOTRUE_BASE_URL=${SERVICE_URL_ADMIN}/gotrue
      - APPFLOWY_WS_BASE_URL=${SERVICE_URL_ADMIN}/ws/v2
    image: appflowyinc/appflowy_web:0.9.132
    depends_on:
      - appflowy_cloud

  appflowy_cloud:
    image: appflowyinc/appflowy_cloud:0.9.149
    environment:
      - RUST_LOG=${RUST_LOG:-info}
      - APPFLOWY_BASE_URL=${SERVICE_URL_ADMIN}
      - APPFLOWY_ENVIRONMENT=production
      - APPFLOWY_DATABASE_URL=postgres://${SERVICE_USER_POSTGRES}:${SERVICE_PASSWORD_POSTGRES}@postgres:5432/${POSTGRES_DB:-appflowy}
      - APPFLOWY_REDIS_URI=redis://redis:6379
      - APPFLOWY_GOTRUE_JWT_SECRET=${SERVICE_PASSWORD_JWT}
      - APPFLOWY_GOTRUE_BASE_URL=http://gotrue:9999
      - APPFLOWY_S3_CREATE_BUCKET=${APPFLOWY_S3_CREATE_BUCKET:-true}
      - APPFLOWY_S3_USE_MINIO=true
      - APPFLOWY_S3_MINIO_URL=http://minio:9000
      - APPFLOWY_S3_ACCESS_KEY=${SERVICE_USER_MINIO}
      - APPFLOWY_S3_SECRET_KEY=${SERVICE_PASSWORD_MINIO}
      - APPFLOWY_S3_BUCKET=${APPFLOWY_S3_BUCKET:-appflowy}
      - APPFLOWY_S3_REGION=${APPFLOWY_S3_REGION:-us-east-1}
      - APPFLOWY_MAILER_SMTP_HOST=${APPFLOWY_MAILER_SMTP_HOST:-smtp.gmail.com}
      - APPFLOWY_MAILER_SMTP_PORT=${APPFLOWY_MAILER_SMTP_PORT:-587}
      - APPFLOWY_MAILER_SMTP_USERNAME=${APPFLOWY_MAILER_SMTP_USERNAME:-notify@appflowy.io}
      - APPFLOWY_MAILER_SMTP_EMAIL=${APPFLOWY_MAILER_SMTP_EMAIL:-notify@appflowy.io}
      - APPFLOWY_MAILER_SMTP_PASSWORD=${APPFLOWY_MAILER_SMTP_PASSWORD:-email_sender_password}
      - APPFLOWY_MAILER_SMTP_TLS_KIND=${APPFLOWY_MAILER_SMTP_TLS_KIND:-none}
      - APPFLOWY_ACCESS_CONTROL=true
      - APPFLOWY_DATABASE_MAX_CONNECTIONS=40
      - AI_SERVER_HOST=ai
      - AI_SERVER_PORT=5001
      - AI_OPENAI_API_KEY=${AI_OPENAI_API_KEY:-}
      - APPFLOWY_WEB_URL=${SERVICE_URL_APPFLOWYWEB}
    healthcheck:
      test: "curl --fail http://127.0.0.1:8000/api/health || exit 1"
      interval: 5s
      timeout: 5s
      retries: 12

    depends_on:
      gotrue:
        condition: service_healthy
      postgres:
        condition: service_healthy
      redis:
        condition: service_started

  gotrue:
    image: appflowyinc/gotrue:0.9.149
    environment:
      - GOTRUE_API_HOST=0.0.0.0
      - GOTRUE_API_PORT=9999
      - PORT=9999
      - GOTRUE_ADMIN_EMAIL=${GOTRUE_ADMIN_EMAIL:-admin@example.com}
      - GOTRUE_ADMIN_PASSWORD=${SERVICE_PASSWORD_ADMIN}
      - GOTRUE_DISABLE_SIGNUP=false
      - GOTRUE_SITE_URL=appflowy-flutter://
      - GOTRUE_URI_ALLOW_LIST=**
      - GOTRUE_JWT_SECRET=${SERVICE_PASSWORD_JWT}
      - GOTRUE_JWT_EXP=${GOTRUE_JWT_EXP:-7200}
      - GOTRUE_DB_DRIVER=postgres
      - API_EXTERNAL_URL=${SERVICE_URL_ADMIN}/gotrue
      - DATABASE_URL=postgres://${SERVICE_USER_POSTGRES}:${SERVICE_PASSWORD_POSTGRES}@postgres:5432/${POSTGRES_DB:-appflowy}?search_path=auth
      - GOTRUE_SMTP_HOST=${GOTRUE_SMTP_HOST}
      - GOTRUE_SMTP_PORT=${GOTRUE_SMTP_PORT:-587}
      - GOTRUE_SMTP_USER=${GOTRUE_SMTP_USER}
      - GOTRUE_SMTP_PASS=${GOTRUE_SMTP_PASS}
      - GOTRUE_MAILER_URLPATHS_CONFIRMATION=/verify
      - GOTRUE_MAILER_URLPATHS_INVITE=/verify
      - GOTRUE_MAILER_URLPATHS_RECOVERY=/verify
      - GOTRUE_MAILER_URLPATHS_EMAIL_CHANGE=/verify
      - GOTRUE_SMTP_ADMIN_EMAIL=${GOTRUE_SMTP_ADMIN_EMAIL}
      - GOTRUE_SMTP_MAX_FREQUENCY=1ns
      - GOTRUE_RATE_LIMIT_EMAIL_SENT=100
      - GOTRUE_MAILER_AUTOCONFIRM=true
    depends_on:
      postgres:
        condition: service_healthy
    healthcheck:
      test: "curl --fail http://127.0.0.1:9999/health || exit 1"
      interval: 5s
      timeout: 5s
      retries: 12

  admin_frontend:
    image: appflowyinc/admin_frontend:0.9.149
    environment:
      - APPFLOWY_GOTRUE_BASE_URL=${SERVICE_URL_ADMIN}/gotrue
      - APPFLOWY_BASE_URL=${SERVICE_URL_ADMIN}
    depends_on:
      gotrue:
        condition: service_healthy
      appflowy_cloud:
        condition: service_started

  ai:
    image: appflowyinc/appflowy_ai:0.9.149
    environment:
      - OPENAI_API_KEY=${AI_OPENAI_API_KEY:-}
      - AI_SERVER_PORT=5001
      - DEFAULT_AI_MODEL=gpt-4.1-mini # Make sure the model is available in your OpenAI account
      - DEFAULT_AI_COMPLETION_MODEL=gpt-4.1-mini # Make sure the model is available in your OpenAI account
      - AI_APPFLOWY_HOST=${SERVICE_URL_APPFLOWYWEB}
      - APPFLOWY_GOTRUE_JWT_SECRET=${SERVICE_PASSWORD_JWT}

      - AZURE_OPENAI_API_KEY=${AZURE_OPENAI_API_KEY}
      - AZURE_OPENAI_ENDPOINT=${AZURE_OPENAI_ENDPOINT}
      - AZURE_OPENAI_API_VERSION=${AZURE_OPENAI_API_VERSION}
      - APPFLOWY_S3_ACCESS_KEY=${SERVICE_USER_MINIO}
      - APPFLOWY_S3_SECRET_KEY=${SERVICE_PASSWORD_MINIO}
      - APPFLOWY_S3_BUCKET=${APPFLOWY_S3_BUCKET:-appflowy}
      - APPFLOWY_S3_REGION=${APPFLOWY_S3_REGION:-us-east-1}
      - AI_DATABASE_URL=postgres://${SERVICE_USER_POSTGRES}:${SERVICE_PASSWORD_POSTGRES}@postgres:5432/${POSTGRES_DB:-appflowy}
      - AI_REDIS_URL=redis://redis:6379
      - AI_USE_MINIO=true
      - AI_MINIO_URL=http://minio:9000
    depends_on:
      postgres:
        condition: service_healthy

  appflowy_worker:
    image: appflowyinc/appflowy_worker:0.9.149
    environment:
      - RUST_LOG=info
      - APPFLOWY_ENVIRONMENT=production
      - APPFLOWY_WORKER_ENVIRONMENT=production
      - APPFLOWY_WORKER_REDIS_URL=redis://redis:6379
      - APPFLOWY_WORKER_DATABASE_URL=postgres://${SERVICE_USER_POSTGRES}:${SERVICE_PASSWORD_POSTGRES}@postgres:5432/${POSTGRES_DB:-appflowy}
      - APPFLOWY_WORKER_DATABASE_NAME=${POSTGRES_DB:-appflowy}
      - APPFLOWY_WORKER_IMPORT_TICK_INTERVAL=30
      - APPFLOWY_S3_USE_MINIO=true
      - APPFLOWY_S3_MINIO_URL=http://minio:9000
      - APPFLOWY_S3_ACCESS_KEY=${SERVICE_USER_MINIO}
      - APPFLOWY_S3_SECRET_KEY=${SERVICE_PASSWORD_MINIO}
      - APPFLOWY_S3_BUCKET=${APPFLOWY_S3_BUCKET:-appflowy}
      - APPFLOWY_S3_REGION=${APPFLOWY_S3_REGION:-us-east-1}
      - APPFLOWY_MAILER_SMTP_HOST=${APPFLOWY_MAILER_SMTP_HOST:-smtp.gmail.com}
      - APPFLOWY_MAILER_SMTP_PORT=${APPFLOWY_MAILER_SMTP_PORT:-587}
      - APPFLOWY_MAILER_SMTP_USERNAME=${APPFLOWY_MAILER_SMTP_USERNAME:-notify@appflowy.io}
      - APPFLOWY_MAILER_SMTP_EMAIL=${APPFLOWY_MAILER_SMTP_EMAIL:-notify@appflowy.io}
      - APPFLOWY_MAILER_SMTP_PASSWORD=${APPFLOWY_MAILER_SMTP_PASSWORD:-email_sender_password}
      - APPFLOWY_MAILER_SMTP_TLS_KIND=${APPFLOWY_MAILER_SMTP_TLS_KIND:-none}
    depends_on:
      postgres:
        condition: service_healthy
      redis:
        condition: service_started

  minio:
    image: minio/minio:RELEASE.2025-09-07T16-13-09Z
    environment:
      - MINIO_ROOT_USER=${SERVICE_USER_MINIO}
      - MINIO_ROOT_PASSWORD=${SERVICE_PASSWORD_MINIO}
    command: server /data --console-address ":9001"
    healthcheck:
      test: ["CMD", "curl", "-f", "http://localhost:9000/minio/health/live"]
      interval: 30s
      timeout: 20s
      retries: 3
    volumes:
      # Coolify will manage this named volume for persistent object storage.
      - minio_data:/data

  postgres:
    image: pgvector/pgvector:pg16
    environment:
      - POSTGRES_USER=${SERVICE_USER_POSTGRES}
      - POSTGRES_DB=${POSTGRES_DB:-appflowy}
      - POSTGRES_PASSWORD=${SERVICE_PASSWORD_POSTGRES}
      - POSTGRES_HOST=postgres
    volumes:
      # Coolify will manage this named volume for persistent database storage.
      - postgres_data:/var/lib/postgresql/data
    healthcheck:
      test: [ "CMD", "pg_isready", "-U", "${SERVICE_USER_POSTGRES}", "-d", "${POSTGRES_DB:-appflowy}" ]
      interval: 5s
      timeout: 5s
      retries: 12

  redis:
    image: redis:8.2.2-alpine3.22
    volumes:
      - "redis_data:/data"
    healthcheck:
      test:
        - CMD-SHELL
        - "redis-cli -h localhost -p 6379 ping"
      interval: 5s
      timeout: 5s
      retries: 3

appwrite.compose:
# documentation: https://appwrite.io/docs
# slogan: A backend-as-a-service platform that simplifies the web & mobile app development.
# category: backend
# tags: backend, backend-as-a-service, platform
# logo: svgs/appwrite.svg

services:
  appwrite:
    image: appwrite/appwrite:1.7.4
    container_name: appwrite
    volumes:
      - appwrite-uploads:/storage/uploads:rw
      - appwrite-imports:/storage/imports:rw
      - appwrite-cache:/storage/cache:rw
      - appwrite-config:/storage/config:rw
      - appwrite-certificates:/storage/certificates:rw
      - appwrite-functions:/storage/functions:rw
      - appwrite-sites:/storage/sites:rw
      - appwrite-builds:/storage/builds:rw
    depends_on:
      - appwrite-mariadb
      - appwrite-redis
    environment:
      - SERVICE_URL_APPWRITE=/
      - _APP_ENV=${_APP_ENV:-production}
      - _APP_EDITION=${_APP_EDITION:-self-hosted}
      - _APP_WORKER_PER_CORE=${_APP_WORKER_PER_CORE:-6}
      - _APP_LOCALE=${_APP_LOCALE:-en}
      - _APP_COMPRESSION_MIN_SIZE_BYTES=${_APP_COMPRESSION_MIN_SIZE_BYTES}
